rules = [
    {
        'name': 'valid_age_range',
        'description': 'Age must be between 0 and 120',
        'severity': 'hard',
        'check': lambda df: df[(df['age'] < 0) | (df['age'] > 120)]
    },
    {
        'name': 'unique_customer_id',
        'description': 'customer_id must have no duplicates',
        'severity': 'hard',
        'check': lambda df: df[df['customer_id'].duplicated()]
    },
    {
        'name': 'plausible_income',
        'description': 'Income above 1 million is unusual, worth a review',
        'severity': 'soft',
        'check': lambda df: df[df['income'] > 1_000_000]
    },
]
